function applyAircraftProfile(id,announce=false){const profile=aircraftProfiles[id]||aircraftProfiles.B738;if(!saved.ownedAircraft.includes(profile.id))return false;activeAircraft=profile;MAX_ALTITUDE_FT=profile.ceiling;saved.selectedAircraft=profile.id;aircraft.scale.set(...profile.scale);const turboprop=profile.id==='Q400';propellerGroups.forEach(p=>p.visible=turboprop);bodyMat.color.set(turboprop?0xe8edf0:0xf3f4f5);wingMat.color.copy(bodyMat.color);redMat.color.set(turboprop?0x176b86:0xb51f2d);goldMat.color.set(turboprop?0x64d4dc:0xe1aa22);$('#modelName').textContent=profile.id==='B738'?'737-800 NG':'DASH 8 Q400';$('#modelSubtitle').textContent=turboprop?'TURBOPROP REGIONAL FLIGHT DECK':'FIXED BASE FLIGHT DECK';$('#aircraftBadge').textContent=`${profile.short} · ${profile.type}`;state.weight=turboprop?29000:65000;if(!state.running)state.fuel=turboprop?4200:7800;const select=$('#aircraftSelect');if(select)select.value=profile.id;if(announce)toast(`已选择 ${profile.name} · ${profile.description}`);saveCareer();return true}
