function drawEICAS(){const{x,w,h}=fitCanvas(ui.eicas);x.fillStyle='#020505';x.fillRect(0,0,w,h);if(!powered()){x.fillStyle='#ff8b25';x.font='11px Consolas';x.fillText('ENG DISPLAY',w/2-38,h/2);return}x.fillStyle='#fff';x.font='10px Consolas';x.fillText('N1',w/2-7,13);state.engineData.forEach((d,i)=>{const runningN1=d.phase==='STABLE'?Math.min(101,22+state.throttle*.78):d.n1,n=Math.max(0,runningN1),cx=i?w*.72:w*.28,cy=43,r=23;x.strokeStyle='#55615c';x.lineWidth=4;x.beginPath();x.arc(cx,cy,r,.7*Math.PI,2.3*Math.PI);x.stroke();x.strokeStyle=d.phase==='HOT'?'#ff4d3d':n>95?'#ff4d3d':'#72e57b';x.beginPath();x.arc(cx,cy,r,.7*Math.PI,(.7+1.6*n/100)*Math.PI);x.stroke();x.fillStyle='#fff';x.font='bold 12px Consolas';x.fillText(n.toFixed(1),cx-16,cy+4);x.fillStyle=d.phase==='HOT'?'#ff4d3d':'#72e57b';x.font='9px Consolas';x.fillText(`N2 ${d.n2.toFixed(1)}`,cx-23,78);x.fillText(`EGT ${Math.round(d.phase==='STABLE'?Math.min(760,d.egt+state.throttle*2.7):d.egt)}`,cx-25,90);x.fillText(`OIL ${Math.round(d.oil)}`,cx-23,102)});x.fillStyle='#fff';x.font='9px Consolas';x.fillText(`FUEL ${Math.round(state.fuel)} KG`,8,h-20);x.fillText(`FLAPS ${state.flaps?['','1','5','15','30','40'][state.flaps]:'UP'}`,8,h-7);x.fillText(`GEAR ${state.gearDown?'DOWN':'UP'}`,w-68,h-7)}
function updateWarnings(){const stall=state.airborne&&state.aoa>=state.criticalAoa-3,gearAlert=state.gearPosition>.15&&state.ias>270,caution=state.running&&(!powered()||state.engines.some(n=>state.ready&&n<20)||(!state.hydraulics&&state.engines.some(n=>n>50))||performance.now()<state.gearWarnUntil||stall||gearAlert||state.gearDamaged);$('#masterCaution').classList.toggle('lit',caution);$('#fireWarn').classList.toggle('lit',state.engines.some(n=>n>103))}
function renderView(){const heading=state.heading*Math.PI/180,pitch=state.pitch*Math.PI/180,viewHeading=heading+lookYaw,viewPitch=THREE.MathUtils.clamp(pitch-lookPitch,-1.35,1.35),forward=new THREE.Vector3(Math.sin(viewHeading)*Math.cos(viewPitch),Math.sin(viewPitch),-Math.cos(viewHeading)*Math.cos(viewPitch));if(state.external){camera.fov=68;const target=new THREE.Vector3(state.x,state.y+1.2,state.z),distance=state.onGround?Math.min(orbitDistance,72):orbitDistance,offset=new THREE.Vector3(-Math.sin(viewHeading)*Math.cos(lookPitch)*distance,Math.sin(lookPitch)*distance+Math.max(16,distance*.3),Math.cos(viewHeading)*Math.cos(lookPitch)*distance);camera.position.lerp(target.clone().add(offset),.12);const noseAim=new THREE.Vector3(Math.sin(heading)*Math.cos(pitch),Math.sin(pitch),-Math.cos(heading)*Math.cos(pitch)).multiplyScalar(18);camera.up.set(0,1,0);camera.lookAt(target.clone().add(noseAim))}else{camera.fov=78;camera.position.set(state.x,state.y+2.45,state.z-1.25);camera.up.set(Math.sin(state.roll*Math.PI/180),Math.cos(state.roll*Math.PI/180),0);camera.lookAt(camera.position.clone().add(forward.multiplyScalar(500)))}camera.updateProjectionMatrix();aircraft.visible=state.external&&!state.crashed;renderer.render(scene,camera)}
function loop(now){requestAnimationFrame(loop);const rawDt=Math.min(1,(now-last)/1000),dt=Math.min(.04,rawDt);last=now;if(state.running){saved.aircraftHours[activeAircraft.id]=(saved.aircraftHours[activeAircraft.id]||0)+dt/3600;updateStartupSystems(rawDt);flightPhysics(dt);updateAutopilotMotionGuard(dt);updateWorld(dt)}else updateStartupSystems(0);updateGearAnimation(dt);updateAircraftSurfaces(dt);updateAircraftLights();state.radioAlt=state.altitude;drawPFD();drawND();drawEICAS();drawExternalHUD();updateWarnings();monitorTutorial();renderView()}populateAircraftSelect();applyAircraftProfile(saved.selectedAircraft);populateAirportSelect();careerMarkup();applyWeather('clear');requestAnimationFrame(loop);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);if(tutorialActive)placeTutorial($(activeTutorialSteps()[tutorialIndex]?.target))});refreshChecklist();
